import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { parseRecap, shortName, systemPrompt, userPrompt } from './recap'
import type { TurnWork } from './recap'

const recap = atom({ plugin: 'cosa-hai-fatto', key: 'recap' } as const, null)
const isThinking = atom({ plugin: 'cosa-hai-fatto', key: 'isThinking' } as const, false)
const isHidden = atom({ plugin: 'cosa-hai-fatto', key: 'isHidden' } as const, false)

const FILE_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])
const EXPLAIN_MORE =
  'Spiegami in parole semplici, come se non sapessi programmare, cosa hai cambiato nell\'ultima risposta, perché, e come posso verificare che funzioni.'

function fileOf(input: unknown): string | undefined {
  if (typeof input !== 'object' || input === null) {
    return undefined
  }
  const record = input as Record<string, unknown>
  const path = record.file_path ?? record.notebook_path
  return typeof path === 'string' ? path : undefined
}

function describedCommand(input: unknown): string | undefined {
  if (typeof input !== 'object' || input === null) {
    return undefined
  }
  const record = input as Record<string, unknown>
  const text = record.description ?? record.command
  return typeof text === 'string' ? text.slice(0, 120) : undefined
}

async function explain($: EngineInterface, work: TurnWork, answer: string, language: string): Promise<void> {
  await update($, isThinking, () => true)
  try {
    const reply = await $.model.complete({
      model: 'haiku',
      system: systemPrompt(language),
      prompt: userPrompt(work, answer),
      maxTokens: 300,
      timeoutMs: 30_000,
    })
    const found = reply.isAnswered ? parseRecap(reply.text, work.files.length) : null
    await update($, recap, () => found)
    await update($, isHidden, () => false)
  } finally {
    await update($, isThinking, () => false)
  }
}

export const register: Register = (on, options) => {
  const language = String(options.language ?? 'italiano').trim() || 'italiano'
  let work: TurnWork = { request: '', files: [], commands: [] }

  on('turn.start', async ($, e, next) => {
    work = { request: e.text, files: [], commands: [] }
    await update($, recap, () => null)

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    const cwd = await $.session.cwd()
    const file = FILE_TOOLS.has(String(e.tool)) ? fileOf(e) : undefined
    if (file !== undefined) {
      const name = shortName(file, cwd)
      if (!work.files.includes(name)) {
        work = { ...work, files: [...work.files, name].slice(0, 30) }
      }
    }
    if (String(e.tool) === 'Bash') {
      const command = describedCommand(e)
      if (command !== undefined) {
        work = { ...work, commands: [...work.commands, command].slice(-8) }
      }
    }

    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    // Only the main conversation's turns, and only when files changed: a plain answer needs no recap.
    if (e.agentId === undefined && e.reason === 'answer' && work.files.length > 0) {
      // A recap that fails leaves the band empty; it never gets in the way of the session.
      void explain($, work, e.answer, language).catch(() => undefined)
    }

    return result
  })

  on('session.end', async ($, e, next) => {
    await update($, recap, () => null)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const below = await next(e)
    const current = await read($, recap)
    const thinking = await read($, isThinking)
    const isQuiet =
      e.props.hasSurvey ||
      e.props.isWorking ||
      e.props.view.agentId !== undefined ||
      (await read($, isHidden)) ||
      (current === null && !thinking)

    if (isQuiet) {
      return below
    }

    const { Box, Button, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="column">
        {current === null ? (
          <Text key="thinking" dimColor>
            💡 Preparo il riassunto in parole semplici…
          </Text>
        ) : (
          <Box key="recap" flexDirection="column">
            <Text>
              <Text bold color="claude">💡 In breve: </Text>
              {current.what}
            </Text>
            {current.tryIt !== null && (
              <Text>
                <Text bold>👉 Prova: </Text>
                {current.tryIt}
              </Text>
            )}
            <Box flexDirection="row" columnGap={1}>
              <Button
                key="more"
                label="Spiegamelo meglio"
                onPress={() => void $.prompt.submit({ text: EXPLAIN_MORE, asUser: true })}
              />
              <Button key="hide" label="Nascondi" onPress={() => update($, isHidden, () => true)} />
            </Box>
          </Box>
        )}
        {below}
      </Box>
    )
  })
}

