import type { Recap } from '../types'

export type TurnWork = {
  request: string
  files: string[]
  commands: string[]
}

export function systemPrompt(language: string): string {
  return [
    `Spieghi a una persona che NON sa programmare cosa ha appena fatto un assistente di programmazione sul suo progetto. Rispondi in ${language}.`,
    'Niente gergo tecnico: niente nomi di file, funzioni, librerie o comandi, a meno che la persona non li abbia usati lei stessa.',
    'Parla di quello che la persona vedrà o potrà fare, non di come è fatto il codice.',
    'Rispondi con esattamente due righe, senza altro testo:',
    'COSA: una o due frasi brevi su cosa è cambiato (massimo 200 caratteri).',
    'PROVA: un passo concreto per vedere la modifica (massimo 120 caratteri), oppure "-" se non c\'è niente da provare.',
  ].join('\n')
}

export function userPrompt(work: TurnWork, answer: string): string {
  const files = work.files.map(file => `- ${file}`).join('\n') || '- (nessuno)'
  const commands = work.commands.map(command => `- ${command}`).join('\n') || '- (nessuno)'

  return [
    `La richiesta della persona:\n${clip(work.request, 1500)}`,
    `I file modificati:\n${files}`,
    `Le azioni eseguite:\n${commands}`,
    `La risposta finale dell'assistente:\n${clip(answer, 4000)}`,
  ].join('\n\n')
}

export function parseRecap(text: string, files: number): Recap | null {
  const what = /^\s*COSA:\s*(.+)$/im.exec(text)?.[1]?.trim()
  if (what === undefined || what.length === 0) {
    return null
  }
  const tryIt = /^\s*PROVA:\s*(.+)$/im.exec(text)?.[1]?.trim()
  const hasTry = tryIt !== undefined && tryIt !== '-' && tryIt.length > 1

  return { what, tryIt: hasTry ? tryIt : null, files }
}

// The file name alone: the model needs a hint of what was touched, not the whole path.
export function shortName(path: string, cwd: string): string {
  const inside = path.startsWith(`${cwd}/`) ? path.slice(cwd.length + 1) : path
  return inside.length > 80 ? `…${inside.slice(-79)}` : inside
}

function clip(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max)}…` : text
}

