export type Recap = {
  /** What changed, in words for someone who does not code. */
  what: string
  /** How to see it working, if there is something to try. */
  tryIt: string | null
  files: number
}

declare module 'claude-code' {
  interface PluginState {
    'cosa-hai-fatto': {
      recap: Recap | null
      isThinking: boolean
      isHidden: boolean
    }
  }
}
